WITH gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) > INTERVAL '30' DAY THEN 1 ELSE 0 END AS is_new_burst FROM payments), sessions_payments AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT s.id, s.order_id, s.method, s.amount, s.paid_at, s.is_new_burst, CASE WHEN method RLIKE '^(bank_transfer|card)$' THEN 'GROUP_A' WHEN method RLIKE '^(paypal|cash)$' THEN 'EXTENDED' ELSE 'OTHER_ZONE' END AS method_zone, (SELECT AVG(x.amount) FROM payments x WHERE x.order_id = s.order_id) AS avg_payment_amount FROM sessions_payments s
